  <script>
    (function () {
      "use strict";

      var storageKey = "snippet-proof-board-v1";

      var els = {
        titleTag: document.getElementById("titleTag"),
        metaDesc: document.getElementById("metaDesc"),
        promise: document.getElementById("promise"),
        notes: document.getElementById("notes"),
        runBtn: document.getElementById("runBtn"),
        copyBtn: document.getElementById("copyBtn"),
        downloadBtn: document.getElementById("downloadBtn"),
        saveBtn: document.getElementById("saveBtn"),
        clearBtn: document.getElementById("clearBtn"),
        notice: document.getElementById("notice"),
        board: document.getElementById("board"),
        brief: document.getElementById("brief"),
        scoreRing: document.getElementById("scoreRing"),
        scoreNumber: document.getElementById("scoreNumber"),
        claimCount: document.getElementById("claimCount"),
        unsupportedCount: document.getElementById("unsupportedCount"),
        avgMatch: document.getElementById("avgMatch"),
        riskCount: document.getElementById("riskCount"),
        statusList: document.getElementById("statusList")
      };

      var state = {
        titleTag: "",
        metaDesc: "",
        promise: "",
        notes: "",
        claims: []
      };

      var stopWords = {
        a: true, an: true, and: true, are: true, as: true, at: true, be: true,
        before: true, by: true, can: true, for: true, from: true, get: true,
        has: true, have: true, how: true, in: true, into: true, is: true,
        it: true, its: true, of: true, on: true, or: true, our: true,
        that: true, the: true, their: true, this: true, to: true, use: true,
        with: true, without: true, your: true, you: true, we: true, will: true,
        what: true, when: true, why: true, guide: true, checklist: true
      };

      var riskRules = [
        { label: "superlative", words: ["best", "top", "#1", "number one", "fastest", "easiest", "ultimate", "leading", "only"] },
        { label: "absolute", words: ["always", "never", "guaranteed", "guarantee", "complete", "all", "every", "none", "no one", "must"] },
        { label: "result promise", words: ["increase", "boost", "double", "save", "reduce", "cut", "eliminate", "rank", "convert", "win", "grow"] },
        { label: "freshness", words: ["latest", "new", "updated", "current", "2026", "2027"] },
        { label: "authority", words: ["proven", "research-backed", "data-backed", "expert", "experts", "study", "studies"] }
      ];

      function setNotice(message) {
        els.notice.textContent = message;
      }

      function normalizeText(text) {
        return String(text || "")
          .toLowerCase()
          .replace(/[’']/g, "")
          .replace(/&/g, " and ")
          .replace(/[^a-z0-9#%$.\s-]/g, " ")
          .replace(/\s+/g, " ")
          .trim();
      }

      function tokens(text) {
        var raw = normalizeText(text).split(/\s+/);
        var out = [];
        raw.forEach(function (word) {
          var cleaned = word.replace(/^[.-]+|[.-]+$/g, "");
          if (!cleaned) return;
          if (cleaned.length < 3 && !/[0-9]/.test(cleaned)) return;
          if (stopWords[cleaned]) return;
          out.push(cleaned);
        });
        return out;
      }

      function unique(list) {
        var seen = {};
        var out = [];
        list.forEach(function (item) {
          var key = String(item || "").toLowerCase();
          if (!key || seen[key]) return;
          seen[key] = true;
          out.push(item);
        });
        return out;
      }

      function splitClaims(text, source) {
        var raw = String(text || "").trim();
        if (!raw) return [];

        var pieces = raw
          .replace(/\s+[|•]\s+/g, ". ")
          .replace(/\s+-\s+/g, ". ")
          .split(/[\n.!?;]+/);

        var claims = [];
        pieces.forEach(function (piece) {
          var cleaned = piece.replace(/\s+/g, " ").trim();
          if (cleaned.length < 4) return;
          claims.push({ text: cleaned, source: source });
        });

        if (!claims.length && raw.length > 0) {
          claims.push({ text: raw, source: source });
        }

        return claims;
      }

      function extractClaims() {
        var combined = []
          .concat(splitClaims(els.titleTag.value, "Title tag"))
          .concat(splitClaims(els.metaDesc.value, "Meta description"))
          .concat(splitClaims(els.promise.value, "Search-result promise"));

        var seen = {};
        var out = [];

        combined.forEach(function (claim) {
          var key = normalizeText(claim.text);
          if (!key || seen[key]) return;
          seen[key] = true;
          out.push(claim);
        });

        return out;
      }

      function getRiskFlags(text) {
        var lower = normalizeText(text);
        var flags = [];

        riskRules.forEach(function (rule) {
          var hit = rule.words.some(function (word) {
            return lower.indexOf(word) !== -1;
          });
          if (hit) flags.push(rule.label);
        });

        if (/\b\d+(\.\d+)?\s?%/.test(lower)) flags.push("specific percentage");
        if (/\$\s?\d|\b\d+\s?(dollars|usd)\b/.test(lower)) flags.push("specific dollar amount");
        if (/\b\d{4}\b/.test(lower)) flags.push("date-sensitive");

        return unique(flags);
      }

      function analyzeClaim(text) {
        var noteText = els.notes.value || "";
        var claimTokens = unique(tokens(text));
        var noteTokens = unique(tokens(noteText));
        var noteMap = {};

        noteTokens.forEach(function (token) {
          noteMap[token] = true;
        });

        var matched = [];
        var missing = [];

        claimTokens.forEach(function (token) {
          if (noteMap[token]) {
            matched.push(token);
          } else {
            missing.push(token);
          }
        });

        var match = claimTokens.length ? matched.length / claimTokens.length : 0;
        var risks = getRiskFlags(text);

        return {
          match: match,
          matched: matched,
          missing: missing.slice(0, 9),
          risks: risks
        };
      }

      function defaultStatus(analysis) {
        if (analysis.match >= 0.62 && analysis.risks.length <= 1) return "backed";
        if (analysis.match >= 0.45 && analysis.risks.length <= 2) return "needs-proof";
        if (analysis.match >= 0.25 || analysis.risks.length > 0) return "soften";
        return "remove";
      }

      function statusLabel(status) {
        var labels = {
          "backed": "Backed",
          "needs-proof": "Needs proof",
          "soften": "Soften",
          "remove": "Remove"
        };
        return labels[status] || "Needs proof";
      }

      function statusValue(status) {
        var values = {
          "backed": 100,
          "needs-proof": 58,
          "soften": 34,
          "remove": 8
        };
        return values[status] || 50;
      }

      function statusReason(claim) {
        if (claim.status === "backed") return "Keep the claim if the evidence stays visible on the page.";
        if (claim.status === "needs-proof") return "Add a citation, example, source, screenshot, data point, or page section that directly supports it.";
        if (claim.status === "soften") return "Replace strong promise language with a narrower, provable version.";
        return "Cut it from the snippet unless new evidence is added.";
      }

      function syncInputsToState() {
        state.titleTag = els.titleTag.value;
        state.metaDesc = els.metaDesc.value;
        state.promise = els.promise.value;
        state.notes = els.notes.value;
      }

      function saveLocal(showMessage) {
        syncInputsToState();
        try {
          localStorage.setItem(storageKey, JSON.stringify(state));
          if (showMessage) setNotice("Saved locally in this browser.");
        } catch (err) {
          if (showMessage) setNotice("Local save failed. Browser storage may be blocked.");
        }
      }

      function loadLocal() {
        try {
          var saved = localStorage.getItem(storageKey);
          if (!saved) return false;

          var parsed = JSON.parse(saved);
          state = {
            titleTag: parsed.titleTag || "",
            metaDesc: parsed.metaDesc || "",
            promise: parsed.promise || "",
            notes: parsed.notes || "",
            claims: Array.isArray(parsed.claims) ? parsed.claims : []
          };

          els.titleTag.value = state.titleTag;
          els.metaDesc.value = state.metaDesc;
          els.promise.value = state.promise;
          els.notes.value = state.notes;
          return true;
        } catch (err) {
          return false;
        }
      }

      function runAudit() {
        syncInputsToState();

        var found = extractClaims();
        state.claims = found.map(function (item) {
          var analysis = analyzeClaim(item.text);
          return {
            id: "claim-" + Math.random().toString(16).slice(2),
            text: item.text,
            source: item.source,
            evidenceNote: "",
            status: defaultStatus(analysis)
          };
        });

        render();
        saveLocal(false);
        setNotice(state.claims.length ? "Audit built. Review each claim card before exporting." : "No claims found yet. Add snippet text and run the audit again.");
      }

      function recalcClaim(claim) {
        var analysis = analyzeClaim(claim.text);
        claim.match = analysis.match;
        claim.matched = analysis.matched;
        claim.missing = analysis.missing;
        claim.risks = analysis.risks;
        return claim;
      }

      function render() {
        state.claims.forEach(recalcClaim);
        renderBoard();
        renderScore();
        els.brief.value = buildBrief();
      }

      function removeChildren(node) {
        while (node.firstChild) node.removeChild(node.firstChild);
      }

      function makeChip(text, tone) {
        var chip = document.createElement("div");
        chip.className = "chip" + (tone ? " " + tone : "");
        chip.textContent = text;
        return chip;
      }

      function renderBoard() {
        removeChildren(els.board);

        if (!state.claims.length) {
          var empty = document.createElement("div");
          empty.className = "empty";
          empty.textContent = "Run a proof audit to create editable claim cards from the title tag, meta description, and search-result promise.";
          els.board.appendChild(empty);
          return;
        }

        state.claims.forEach(function (claim, index) {
          var card = document.createElement("article");
          card.className = "claim-card";

          var top = document.createElement("div");
          top.className = "claim-top";

          var title = document.createElement("h3");
          title.textContent = "Claim " + (index + 1);

          var source = document.createElement("div");
          source.className = "source-tag";
          source.textContent = claim.source;

          top.appendChild(title);
          top.appendChild(source);

          var claimField = document.createElement("div");
          claimField.className = "field";

          var claimLabel = document.createElement("label");
          claimLabel.textContent = "Claim text";

          var claimInput = document.createElement("textarea");
          claimInput.className = "claim-text";
          claimInput.value = claim.text;
          claimInput.addEventListener("input", function () {
            claim.text = claimInput.value;
            recalcClaim(claim);
            renderScore();
            els.brief.value = buildBrief();
            saveLocal(false);
            refreshCardAnalysis(card, claim);
          });

          claimField.appendChild(claimLabel);
          claimField.appendChild(claimInput);

          var chips = document.createElement("div");
          chips.className = "chip-row";
          chips.setAttribute("data-chip-row", "true");

          card.appendChild(top);
          card.appendChild(claimField);
          card.appendChild(chips);

          var controls = document.createElement("div");
          controls.className = "claim-controls";

          var evidenceField = document.createElement("div");
          evidenceField.className = "field";

          var evidenceLabel = document.createElement("label");
          evidenceLabel.textContent = "Evidence note or rewrite instruction";

          var evidenceInput = document.createElement("textarea");
          evidenceInput.value = claim.evidenceNote || "";
          evidenceInput.placeholder = "Example: add source link, cite page section, soften wording, or remove the claim.";
          evidenceInput.addEventListener("input", function () {
            claim.evidenceNote = evidenceInput.value;
            els.brief.value = buildBrief();
            saveLocal(false);
          });

          evidenceField.appendChild(evidenceLabel);
          evidenceField.appendChild(evidenceInput);

          var statusField = document.createElement("div");
          statusField.className = "field";

          var statusLabelEl = document.createElement("label");
          statusLabelEl.textContent = "Decision";

          var select = document.createElement("select");
          [
            ["backed", "Backed"],
            ["needs-proof", "Needs proof"],
            ["soften", "Soften"],
            ["remove", "Remove"]
          ].forEach(function (pair) {
            var option = document.createElement("option");
            option.value = pair[0];
            option.textContent = pair[1];
            select.appendChild(option);
          });

          select.value = claim.status;
          select.addEventListener("change", function () {
            claim.status = select.value;
            renderScore();
            els.brief.value = buildBrief();
            saveLocal(false);
            refreshCardAnalysis(card, claim);
          });

          statusField.appendChild(statusLabelEl);
          statusField.appendChild(select);

          controls.appendChild(evidenceField);
          controls.appendChild(statusField);

          card.appendChild(controls);
          els.board.appendChild(card);

          refreshCardAnalysis(card, claim);
        });
      }

      function refreshCardAnalysis(card, claim) {
        var chipRow = card.querySelector("[data-chip-row]");
        if (!chipRow) return;

        removeChildren(chipRow);

        var matchPercent = Math.round((claim.match || 0) * 100);
        var matchTone = matchPercent >= 60 ? "good" : matchPercent >= 35 ? "warn" : "danger";
        chipRow.appendChild(makeChip("Evidence match: " + matchPercent + "%", matchTone));

        if (claim.risks && claim.risks.length) {
          chipRow.appendChild(makeChip("Risk flags: " + claim.risks.join(", "), "warn"));
        } else {
          chipRow.appendChild(makeChip("Risk flags: none detected", "good"));
        }

        if (claim.missing && claim.missing.length) {
          chipRow.appendChild(makeChip("Missing support terms: " + claim.missing.join(", "), "danger"));
        } else {
          chipRow.appendChild(makeChip("Missing support terms: none", "good"));
        }
      }

      function renderScore() {
        var total = state.claims.length;
        var unsupported = 0;
        var riskTotal = 0;
        var matchTotal = 0;
        var statusTotal = 0;

        state.claims.forEach(function (claim) {
          matchTotal += claim.match || 0;
          riskTotal += claim.risks ? claim.risks.length : 0;
          statusTotal += statusValue(claim.status);
          if (claim.status !== "backed") unsupported += 1;
        });

        var avgMatchValue = total ? matchTotal / total : 0;
        var statusAvg = total ? statusTotal / total : 0;
        var riskPenalty = total ? Math.min(28, (riskTotal / total) * 8) : 0;
        var score = total ? Math.max(0, Math.min(100, Math.round((avgMatchValue * 46) + (statusAvg * 0.54) - riskPenalty))) : 0;

        els.scoreRing.style.setProperty("--score", String(score));
        els.scoreNumber.textContent = String(score);
        els.claimCount.textContent = String(total);
        els.unsupportedCount.textContent = String(unsupported);
        els.avgMatch.textContent = String(Math.round(avgMatchValue * 100)) + "%";
        els.riskCount.textContent = String(riskTotal);

        renderStatusList(total, unsupported, riskTotal, score);
      }

      function renderStatusList(total, unsupported, riskTotal, score) {
        removeChildren(els.statusList);

        var lines = [];

        if (!total) {
          lines.push(["No audit yet", "Paste snippet text and run the proof audit."]);
        } else if (score >= 80) {
          lines.push(["Snippet is mostly backed", "Check any remaining proof notes before publishing."]);
        } else if (score >= 55) {
          lines.push(["Snippet needs tightening", "Some claims need proof, softer wording, or narrower promises."]);
        } else {
          lines.push(["High rewrite risk", "The snippet is making promises the notes do not clearly support."]);
        }

        if (unsupported) {
          lines.push([unsupported + " claim decisions open", "Anything not marked backed should be fixed before final QA."]);
        }

        if (riskTotal) {
          lines.push([riskTotal + " wording risk flags", "Superlatives, absolutes, freshness claims, and result promises need direct support."]);
        }

        lines.forEach(function (line) {
          var item = document.createElement("div");
          item.className = "status-pill";

          var strong = document.createElement("strong");
          strong.textContent = line[0];

          var span = document.createElement("span");
          span.textContent = line[1];

          item.appendChild(strong);
          item.appendChild(span);
          els.statusList.appendChild(item);
        });
      }

      function buildBrief() {
        var lines = [];
        var unsupported = state.claims.filter(function (claim) {
          return claim.status !== "backed";
        });
        var backed = state.claims.filter(function (claim) {
          return claim.status === "backed";
        });

        var scoreText = els.scoreNumber ? els.scoreNumber.textContent : "0";

        lines.push("SEARCH SNIPPET REWRITE BRIEF");
        lines.push("");
        lines.push("Evidence score: " + scoreText + "/100");
        lines.push("Claims audited: " + state.claims.length);
        lines.push("Claims needing proof, softening, or removal: " + unsupported.length);
        lines.push("");

        lines.push("Current snippet:");
        lines.push("Title tag: " + (els.titleTag.value.trim() || "[missing]"));
        lines.push("Meta description: " + (els.metaDesc.value.trim() || "[missing]"));
        lines.push("Search-result promise: " + (els.promise.value.trim() || "[missing]"));
        lines.push("");

        if (!state.claims.length) {
          lines.push("No claim cards yet. Run the proof audit first.");
          return lines.join("\n");
        }

        if (unsupported.length) {
          lines.push("Fix first:");
          unsupported.forEach(function (claim, index) {
            var riskText = claim.risks && claim.risks.length ? claim.risks.join(", ") : "none detected";
            var missingText = claim.missing && claim.missing.length ? claim.missing.join(", ") : "none";
            lines.push((index + 1) + ". " + statusLabel(claim.status) + " — " + claim.text);
            lines.push("   Source: " + claim.source);
            lines.push("   Evidence match: " + Math.round((claim.match || 0) * 100) + "%");
            lines.push("   Risk flags: " + riskText);
            lines.push("   Missing support terms: " + missingText);
            lines.push("   Action: " + statusReason(claim));
            if (claim.evidenceNote && claim.evidenceNote.trim()) {
              lines.push("   Note: " + claim.evidenceNote.trim());
            }
          });
          lines.push("");
        }

        if (backed.length) {
          lines.push("Safe to keep if page evidence remains visible:");
          backed.forEach(function (claim, index) {
            lines.push((index + 1) + ". " + claim.text + " [" + claim.source + "]");
          });
          lines.push("");
        }

        lines.push("Rewrite direction:");
        if (unsupported.length) {
          lines.push("Use only the backed claims in the snippet. Replace broad promises with specific page contents. Add direct evidence before using any superlative, absolute, freshness, authority, numeric, or result claim.");
        } else {
          lines.push("Current snippet is broadly aligned with the supporting notes. Keep the wording specific and make sure the page visibly supports each claim.");
        }

        return lines.join("\n");
      }

      function copyBrief() {
        els.brief.value = buildBrief();

        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(els.brief.value).then(function () {
            setNotice("Rewrite brief copied.");
          }).catch(function () {
            fallbackCopy();
          });
        } else {
          fallbackCopy();
        }
      }

      function fallbackCopy() {
        els.brief.focus();
        els.brief.select();
        try {
          document.execCommand("copy");
          setNotice("Rewrite brief copied.");
        } catch (err) {
          setNotice("Copy failed. Select the brief text and copy it manually.");
        }
      }

      function downloadBrief() {
        els.brief.value = buildBrief();

        var blob = new Blob([els.brief.value], { type: "text/plain;charset=utf-8" });
        var url = URL.createObjectURL(blob);
        var a = document.createElement("a");
        var stamp = new Date().toISOString().slice(0, 10);

        a.href = url;
        a.download = "snippet-proof-brief-" + stamp + ".txt";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);

        setTimeout(function () {
          URL.revokeObjectURL(url);
        }, 200);

        setNotice("Brief downloaded.");
      }

      function clearBoard() {
        state = {
          titleTag: "",
          metaDesc: "",
          promise: "",
          notes: "",
          claims: []
        };

        els.titleTag.value = "";
        els.metaDesc.value = "";
        els.promise.value = "";
        els.notes.value = "";

        try {
          localStorage.removeItem(storageKey);
        } catch (err) {}

        render();
        setNotice("Board cleared.");
      }

      function bindAutosave() {
        [els.titleTag, els.metaDesc, els.promise, els.notes].forEach(function (input) {
          input.addEventListener("input", function () {
            syncInputsToState();
            if (state.claims.length) {
              state.claims.forEach(recalcClaim);
              renderScore();
              els.brief.value = buildBrief();
              state.claims.forEach(recalcClaim);
            }
            saveLocal(false);
          });
        });
      }

      els.runBtn.addEventListener("click", runAudit);
      els.copyBtn.addEventListener("click", copyBrief);
      els.downloadBtn.addEventListener("click", downloadBrief);
      els.saveBtn.addEventListener("click", function () {
        saveLocal(true);
      });
      els.clearBtn.addEventListener("click", clearBoard);

      bindAutosave();

      var hadSaved = loadLocal();
      if (hadSaved && state.claims.length) {
        render();
        setNotice("Loaded your saved board.");
      } else {
        syncInputsToState();
        render();
      }
    })();
  </script>
</body>
</html>
